SELECT COUNT(*)
  FROM TB_CLMEMX MEMBER
  JOIN TM_USERXM USERX ON USERX.USER_NUMB = MEMBER.USER_NUMB AND USERX.USER_STAT = #{userActive}
 WHERE MEMBER.CLUB_NUMB = #{clubNumb} AND MEMBER.USER_NUMB = #{userNumb}
   AND MEMBER.MEMB_STAT = #{memberActive}

SELECT /* getClubChatList */ CHAT.CHAT_NUMB , CHAT.CLUB_NUMB , CHAT.USER_NUMB , USERX.USER_NICK , FILEX.FILE_PATH AS PORF_PATH , CHAT.CHAT_TYPE , CHAT.CHAT_CNTN , CHAT.CLNT_UUID , CASE WHEN CHAT.USER_NUMB = #{userNumb} THEN #{commYes} ELSE #{commNo} END AS MINE_YSNO , COUNT(READUSER.USER_NUMB) AS UNREAD_CNT , CHAT.REGI_DATE FROM TM_CLCHAT CHAT LEFT JOIN TM_USERXM USERX ON USERX.USER_NUMB = CHAT.USER_NUMB LEFT JOIN TM_FILEXM FILEX ON FILEX.FILE_NUMB = USERX.PROF_NUMB LEFT JOIN TB_CLMEMX READER ON READER.CLUB_NUMB = CHAT.CLUB_NUMB AND READER.MEMB_STAT = #{memberActive} AND READER.USER_NUMB != CHAT.USER_NUMB AND READER.USER_NUMB != #{userNumb} AND READER.JOIN_DATE <= CHAT.REGI_DATE AND COALESCE(READER.READ_NUMB, 0) < CHAT.CHAT_NUMB LEFT JOIN TM_USERXM READUSER ON READUSER.USER_NUMB = READER.USER_NUMB AND READUSER.USER_STAT = #{userActive} WHERE CHAT.CLUB_NUMB = #{clubNumb} AND CHAT.DELT_YSNO = #{commNo}
AND CHAT.CHAT_NUMB > #{afterChatNumb}
AND CHAT.CHAT_NUMB IN ( SELECT RECENT_PAGE.CHAT_NUMB FROM ( SELECT RECENT.CHAT_NUMB FROM TM_CLCHAT RECENT WHERE RECENT.CLUB_NUMB = #{clubNumb} AND RECENT.DELT_YSNO = #{commNo} ORDER BY RECENT.CHAT_NUMB DESC LIMIT #{maxSize} ) RECENT_PAGE )
GROUP BY CHAT.CHAT_NUMB , CHAT.CLUB_NUMB , CHAT.USER_NUMB , USERX.USER_NICK , FILEX.FILE_PATH , CHAT.CHAT_TYPE , CHAT.CHAT_CNTN , CHAT.CLNT_UUID , CHAT.REGI_DATE ORDER BY CHAT.CHAT_NUMB LIMIT #{maxSize}

