UPDATE /* uptClubChatRead */ TB_CLMEMX MEMBER
  JOIN TM_USERXM USERX
    ON USERX.USER_NUMB = MEMBER.USER_NUMB
   AND USERX.USER_STAT = #{userActive}
  JOIN TM_CLCHAT CHAT
    ON CHAT.CHAT_NUMB = #{chatNumb}
   AND CHAT.CLUB_NUMB = MEMBER.CLUB_NUMB
   AND CHAT.DELT_YSNO = #{commNo}
   SET MEMBER.READ_NUMB = GREATEST(COALESCE(MEMBER.READ_NUMB, 0), CHAT.CHAT_NUMB)
     , MEMBER.UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE MEMBER.CLUB_NUMB = #{clubNumb}
   AND MEMBER.USER_NUMB = #{userNumb}
   AND MEMBER.MEMB_STAT = #{memberActive}

