SELECT RECOMMEND.RECM_NUMB, BOOK.BOOK_NUMB, BOOK.BOOK_TITL, BOOK.BOOK_ATHR, BOOK.BOOK_PUBL , BOOK.BOOK_ISBN, BOOK.BOOK_CVIM, BOOK.BOOK_DESC, DATE_FORMAT(BOOK.PUBL_DATE, '%Y-%m-%d') AS PUBL_DATE , USERX.USER_NICK , CASE WHEN RECOMMEND.USER_NUMB = #{userNumb} THEN #{commYes} ELSE #{commNo} END AS MINE_YSNO , CASE WHEN VOTE.USER_NUMB IS NULL THEN #{commNo} ELSE #{commYes} END AS VOTE_YSNO , COALESCE(VOTES.VOTE_CNT, 0) AS VOTE_CNT FROM TB_CLBREC RECOMMEND JOIN TM_BKINFO BOOK ON BOOK.BOOK_NUMB = RECOMMEND.BOOK_NUMB JOIN TM_USERXM USERX ON USERX.USER_NUMB = RECOMMEND.USER_NUMB AND USERX.USER_STAT = #{userActive} LEFT JOIN TB_CLBVOT VOTE ON VOTE.CLUB_NUMB = RECOMMEND.CLUB_NUMB AND VOTE.RECM_NUMB = RECOMMEND.RECM_NUMB AND VOTE.USER_NUMB = #{userNumb} LEFT JOIN ( SELECT BALLOT.CLUB_NUMB , BALLOT.RECM_NUMB , COUNT(*) AS VOTE_CNT FROM TB_CLBVOT BALLOT WHERE BALLOT.CLUB_NUMB = #{clubNumb} GROUP BY BALLOT.CLUB_NUMB , BALLOT.RECM_NUMB ) VOTES ON VOTES.CLUB_NUMB = RECOMMEND.CLUB_NUMB AND VOTES.RECM_NUMB = RECOMMEND.RECM_NUMB WHERE RECOMMEND.CLUB_NUMB = #{clubNumb}
AND RECOMMEND.REGI_DATE >= #{cycleStdt}
ORDER BY RECOMMEND.REGI_DATE, RECOMMEND.RECM_NUMB


