UPDATE /* uptMemberExit */ TB_CLMEMX MEMBER
  JOIN TM_CLUBXM CLUB
    ON CLUB.CLUB_NUMB = MEMBER.CLUB_NUMB
   AND CLUB.OWNR_NUMB = #{ownerNumb}
   AND CLUB.CLUB_STAT = #{clubActive}
  JOIN TM_USERXM OWNER
    ON OWNER.USER_NUMB = #{ownerNumb}
   AND OWNER.USER_STAT = #{userActive}
  JOIN TM_USERXM TARGET
    ON TARGET.USER_NUMB = MEMBER.USER_NUMB
   AND TARGET.USER_STAT = #{userActive}
   SET MEMBER.MEMB_STAT = #{memberExited}
     , MEMBER.EXIT_DATE = CURRENT_TIMESTAMP(6)
     , MEMBER.BLOC_YSNO = #{commYes}
     , MEMBER.UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE MEMBER.CLUB_NUMB = #{clubNumb}
   AND MEMBER.USER_NUMB = #{targetUserNumb}
   AND MEMBER.MEMB_ROLE = #{memberRole}
   AND MEMBER.MEMB_STAT = #{memberActive}

