          , CASE WHEN #{request.goalStdt} <= CURRENT_DATE THEN #{roundReading}
                 ELSE #{roundScheduled}
            END
          , #{request.goalStdt}
          , #{request.goalEndt}
          , CASE WHEN #{request.goalStdt} <= CURRENT_DATE THEN CURRENT_TIMESTAMP(6)
                 ELSE NULL
            END
          , #{request.idemKeyx}
          , #{userNumb}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)


