SELECT /* getWrittenReadingReportCnt */
       COUNT(*)
  FROM TB_CLPART PART
  JOIN TM_REPORT REPORT
    ON REPORT.REPT_NUMB = PART.REPT_NUMB
 WHERE PART.CLUB_NUMB = #{clubNumb}
   AND PART.ROND_NUMB = #{rondNumb}
   AND (   REPORT.REPT_STAT != #{reportRead}
        OR TRIM(COALESCE(REPORT.REPT_CNTN, '')) != ''
        OR CAST(COALESCE(REPORT.REPT_GRDE, '0') AS DECIMAL(3, 1)) > 0
       )

