UPDATE /* uptReading */
       TM_CLRNDX
   SET BOOK_NUMB = #{request.bookNumb}
     , GOAL_STDT = #{request.goalStdt}
     , GOAL_ENDT = #{request.goalEndt}
     , ROND_STAT = CASE WHEN #{request.goalStdt} <= CURRENT_DATE THEN #{roundReading}
                        ELSE #{roundScheduled}
                   END
     , OPEN_DATE = CASE WHEN #{request.goalStdt} <= CURRENT_DATE
                        THEN COALESCE(OPEN_DATE, CURRENT_TIMESTAMP(6))
                        ELSE NULL
                   END
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE CLUB_NUMB = #{clubNumb}
   AND ROND_NUMB = #{rondNumb}
   AND ROND_STAT IN (#{roundScheduled}, #{roundReading})

UPDATE /* uptReadingReportList */
       TM_REPORT REPORT
  JOIN TB_CLPART PART
    ON PART.REPT_NUMB = REPORT.REPT_NUMB
   SET REPORT.BOOK_NUMB = #{request.bookNumb}
     , REPORT.REPT_STDT = #{request.goalStdt}
     , REPORT.REPT_ENDT = #{request.goalEndt}
     , REPORT.UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE PART.CLUB_NUMB = #{clubNumb}
   AND PART.ROND_NUMB = #{rondNumb}


UPDATE /* uptEarlyReadingGoal */
       TB_CLPART PART
  JOIN TM_CLRNDX ROUNDX
    ON ROUNDX.CLUB_NUMB = PART.CLUB_NUMB
   AND ROUNDX.ROND_NUMB = PART.ROND_NUMB
   AND ROUNDX.ROND_STAT = #{roundCompleted}
  JOIN TB_CLMEMX MEMBER
    ON MEMBER.CLUB_NUMB = PART.CLUB_NUMB
   AND MEMBER.USER_NUMB = PART.USER_NUMB
   AND MEMBER.MEMB_STAT = #{memberActive}
  JOIN TM_USERXM USERX
    ON USERX.USER_NUMB = PART.USER_NUMB
   AND USERX.USER_STAT = #{userActive}
  JOIN TM_REPORT REPORT
    ON REPORT.REPT_NUMB = PART.REPT_NUMB
   AND REPORT.USER_NUMB = PART.USER_NUMB
   AND REPORT.REPT_STAT = #{reportDone}
   SET PART.GOAL_YSNO = #{commYes}
     , PART.ACHV_DATE = COALESCE(PART.ACHV_DATE, CURRENT_TIMESTAMP(6))
     , PART.UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE PART.CLUB_NUMB = #{clubNumb}
   AND PART.ROND_NUMB = #{rondNumb}
   AND PART.ANON_YSNO = #{commNo}
   AND PART.GOAL_YSNO IS NULL

