SELECT /* getClubDtl */
, MINE.MEMB_STAT , MINE.MEMB_ROLE , APPLICATION.JOIN_STAT , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_ROUND.ROND_NUMB END AS CURRENT_ROND_NUMB , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_ROUND.ROND_STAT END AS CURRENT_ROND_STAT , CASE WHEN (MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive})) AND CURRENT_ROUND.ROND_NUMB IS NOT NULL THEN CURRENT_ROUND.ROND_NUMB WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN COALESCE(( SELECT MAX(ROUNDX.ROND_NUMB) FROM TM_CLRNDX ROUNDX WHERE ROUNDX.CLUB_NUMB = CLUB.CLUB_NUMB ), 0) + 1 END AS READING_ORDR , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_BOOK.BOOK_TITL END AS CURRENT_BOOK_TITL , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_BOOK.BOOK_NUMB END AS CURRENT_BOOK_NUMB , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_BOOK.BOOK_ATHR END AS CURRENT_BOOK_ATHR , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_BOOK.BOOK_CVIM END AS CURRENT_BOOK_CVIM , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_BOOK.BOOK_PUBL END AS CURRENT_BOOK_PUBL , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_BOOK.BOOK_ISBN END AS CURRENT_BOOK_ISBN , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_BOOK.BOOK_DESC END AS CURRENT_BOOK_DESC , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN DATE_FORMAT(CURRENT_BOOK.PUBL_DATE, '%Y-%m-%d') END AS CURRENT_PUBL_DATE , CASE WHEN MINE.MEMB_STAT = #{memberActive} AND MINE.MEMB_ROLE = #{ownerRole} THEN NOT EXISTS ( SELECT 1 FROM TB_CLPART MANAGE_PART JOIN TM_REPORT MANAGE_REPORT ON MANAGE_REPORT.REPT_NUMB = MANAGE_PART.REPT_NUMB WHERE MANAGE_PART.CLUB_NUMB = CURRENT_ROUND.CLUB_NUMB AND MANAGE_PART.ROND_NUMB = CURRENT_ROUND.ROND_NUMB AND ( MANAGE_REPORT.REPT_STAT != #{reportRead} OR TRIM(COALESCE(MANAGE_REPORT.REPT_CNTN, '')) != '' OR CAST(COALESCE(MANAGE_REPORT.REPT_GRDE, '0') AS DECIMAL(3, 1)) > 0 ) ) END AS CURRENT_BOOK_CHANGE_ALLOWED , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_ROUND.GOAL_STDT END AS CURRENT_GOAL_STDT , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN CURRENT_ROUND.GOAL_ENDT END AS CURRENT_GOAL_ENDT , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_REPORT.REPT_STAT END AS CURRENT_REPORT_STAT , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_REPORT.REPT_NUMB END AS CURRENT_REPORT_NUMB , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN COALESCE(CURRENT_REPORT_COUNT.REPORT_CNT, 0) END AS CURRENT_REPORT_CNT , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN COALESCE(CURRENT_GOAL.GOAL_ACHV_CNT, 0) END AS CURRENT_GOAL_ACHV_CNT , CASE WHEN MINE.MEMB_STAT = #{memberActive} OR (CLUB.CLUB_VISB = #{clubPublic} AND CLUB.CLUB_STAT = #{clubActive}) THEN COALESCE(CURRENT_GOAL.GOAL_MEMB_CNT, 0) END AS CURRENT_GOAL_MEMB_CNT FROM TM_CLUBXM CLUB LEFT JOIN TM_USERXM OWNER ON OWNER.USER_NUMB = CLUB.OWNR_NUMB
LEFT JOIN TB_CLMEMX MINE ON MINE.CLUB_NUMB = CLUB.CLUB_NUMB AND MINE.USER_NUMB = #{userNumb} AND MINE.MEMB_STAT = #{memberActive} LEFT JOIN ( SELECT RECENT.CLUB_NUMB , RECENT.USER_NUMB , RECENT.JOIN_STAT FROM ( SELECT APPLICATION.CLUB_NUMB , APPLICATION.USER_NUMB , APPLICATION.JOIN_STAT , ROW_NUMBER() OVER ( PARTITION BY APPLICATION.CLUB_NUMB, APPLICATION.USER_NUMB ORDER BY APPLICATION.APPL_NUMB DESC ) AS ROW_NUMB FROM TB_CLJOIN APPLICATION WHERE APPLICATION.USER_NUMB = #{userNumb} AND ( APPLICATION.JOIN_STAT = #{applicationPending} OR (APPLICATION.JOIN_STAT = #{applicationRejected} AND APPLICATION.PROC_DATE > DATE_SUB( CURRENT_TIMESTAMP(6), INTERVAL #{reapplyWaitDays} DAY ))) ) RECENT WHERE RECENT.ROW_NUMB = 1 ) APPLICATION ON APPLICATION.CLUB_NUMB = CLUB.CLUB_NUMB AND APPLICATION.USER_NUMB = #{userNumb}
LEFT JOIN ( SELECT PART.CLUB_NUMB , PART.ROND_NUMB , COUNT(*) AS REPORT_CNT FROM TB_CLPART PART JOIN TM_REPORT REPORT ON REPORT.REPT_NUMB = PART.REPT_NUMB AND REPORT.USER_NUMB = PART.USER_NUMB AND REPORT.REPT_STAT = #{reportDone} JOIN TB_CLMEMX MEMBER ON MEMBER.CLUB_NUMB = PART.CLUB_NUMB AND MEMBER.USER_NUMB = PART.USER_NUMB AND MEMBER.MEMB_STAT = #{memberActive} JOIN TM_USERXM USERX ON USERX.USER_NUMB = PART.USER_NUMB AND USERX.USER_STAT = #{userActive} WHERE PART.CLUB_NUMB = #{clubNumb} AND PART.ANON_YSNO = #{commNo} GROUP BY PART.CLUB_NUMB , PART.ROND_NUMB ) CURRENT_REPORT_COUNT ON CURRENT_REPORT_COUNT.CLUB_NUMB = CURRENT_ROUND.CLUB_NUMB AND CURRENT_REPORT_COUNT.ROND_NUMB = CURRENT_ROUND.ROND_NUMB LEFT JOIN TM_BKINFO CURRENT_BOOK ON CURRENT_BOOK.BOOK_NUMB = CURRENT_ROUND.BOOK_NUMB LEFT JOIN TB_CLPART CURRENT_PART ON CURRENT_PART.CLUB_NUMB = CURRENT_ROUND.CLUB_NUMB AND CURRENT_PART.ROND_NUMB = CURRENT_ROUND.ROND_NUMB AND CURRENT_PART.USER_NUMB = #{userNumb} LEFT JOIN TM_REPORT CURRENT_REPORT ON CURRENT_REPORT.REPT_NUMB = CURRENT_PART.REPT_NUMB AND CURRENT_REPORT.USER_NUMB = #{userNumb}
WHERE CLUB.CLUB_NUMB = #{clubNumb}

mapper.delete:

DELETE /* delMemberRestriction */ MEMBER
  FROM TB_CLMEMX MEMBER
  JOIN TM_CLUBXM CLUB
    ON CLUB.CLUB_NUMB = MEMBER.CLUB_NUMB
   AND CLUB.OWNR_NUMB = #{ownerNumb}
 WHERE MEMBER.CLUB_NUMB = #{clubNumb}
   AND MEMBER.USER_NUMB = #{targetUserNumb}
   AND MEMBER.MEMB_STAT = #{memberExited}
   AND MEMBER.BLOC_YSNO = #{commYes}

