/* setJoinApplication */
INSERT INTO TB_CLJOIN (
            CLUB_NUMB
          , APPL_NUMB
          , USER_NUMB
          , QUES_FIRS
          , QUES_SECO
          , QUES_THIR
          , QUES_FOUR
          , QUES_FIFT
          , ANSR_FIRS
          , ANSR_SECO
          , ANSR_THIR
          , ANSR_FOUR
          , ANSR_FIFT
          , JOIN_STAT
          , APPL_DATE
)
SELECT #{clubNumb}
     , COALESCE(MAX(APPL_NUMB), 0) + 1
     , #{userNumb}
     , #{quesFirs}
     , #{quesSeco,jdbcType=VARCHAR}
     , #{quesThir,jdbcType=VARCHAR}
     , #{quesFour,jdbcType=VARCHAR}
     , #{quesFift,jdbcType=VARCHAR}
     , #{ansrFirs}
     , #{ansrSeco,jdbcType=VARCHAR}
     , #{ansrThir,jdbcType=VARCHAR}
     , #{ansrFour,jdbcType=VARCHAR}
     , #{ansrFift,jdbcType=VARCHAR}
     , #{applicationPending}
     , CURRENT_TIMESTAMP(6)
  FROM TB_CLJOIN
 WHERE CLUB_NUMB = #{clubNumb}

